382: bool EstablishOrCheckMainThread(bool establish, bool required) noexcept
383: {
384:     if (!g_shared)
385:         return false;
386:     const LONG thread = static_cast<LONG>(GetCurrentThreadId());
387:     LONG main_thread = InterlockedCompareExchange(&g_shared->main_thread_id, 0, 0);
388:     if (!main_thread && establish)
389:     {
390:         InterlockedCompareExchange(&g_shared->main_thread_id, thread, 0);
391:         main_thread = InterlockedCompareExchange(&g_shared->main_thread_id, 0, 0);
392:     }
393:     // Installation can finish in the middle of an existing loop iteration.  Until the
394:     // next clock anchor freezes the main thread, non-clock hooks are bootstrap
395:     // passthroughs: they must neither fabricate iteration-zero evidence nor classify
396:     // an as-yet unknown thread as a mismatch.
397:     if (!main_thread)
398:         return false;
399:     const bool matches = main_thread && main_thread == thread;
400:     if (required && !matches)
401:         ReportUnsafe(ErrorCode::WrongThread);
402:     return matches;
403: }
