1108: extern "C" void __fastcall AlternateOwnerHook(void* self, void*)
1109: {
1110:     HookScope scope;
1111:     PhaseScope phase_scope(Phase::GameplayUpdate);
1112:     const bool observe = Armed() && EstablishOrCheckMainThread(false, true);
1113:     std::uint32_t before = 0;
1114:     const bool readable = ReadAlternateFlag(self, before);
1115:     if (observe && !readable)
1116:         ReportUnsafe(ErrorCode::HookTransaction);
1117:     const bool entered = observe && readable && Armed();
1118:     bool tracked = false;
1119:     if (entered)
1120:     {
1121:         NativeEvent event = Event(EventKind::AlternateOwnerEnter, Phase::GameplayUpdate);
1122:         event.return_rva = ReturnRva(_ReturnAddress());
1123:         event.value_bits = before;
1124:         Publish(event);
1125:         tracked = g_tls_alternate_envelope.BeginOwner() !=
1126:                   detail::AlternateEnvelopeTransition::Invalid;
1127:         if (!tracked)
1128:         {
1129:             g_tls_alternate_envelope.Reset();
1130:             g_tls_alternate_owner = nullptr;
1131:             ReportUnsafe(ErrorCode::HookTransaction);
1132:         }
1133:         else
1134:             g_tls_alternate_owner = self;
1135:     }
1136:     g_alternate_owner(self);
1137:     if (entered)
1138:     {
1139:         if (tracked)
1140:         {
1141:             const auto transition = g_tls_alternate_envelope.EndOwner();
1142:             if (transition == detail::AlternateEnvelopeTransition::Close &&
1143:                 Armed() && g_lifecycle_observation)
1144:                 g_lifecycle_observation(
1145:                     EmbeddedLifecycleSignal::AlternateEnvelope, false,
1146:                     g_tls_alternate_owner, _ReturnAddress(),
1147:                     g_lifecycle_observation_context);
1148:             if (transition == detail::AlternateEnvelopeTransition::Invalid)
1149:                 ReportUnsafe(ErrorCode::HookTransaction);
1150:             g_tls_alternate_owner = nullptr;
1151:         }
1152:         std::uint32_t after = 0;
1153:         const bool after_readable = ReadAlternateFlag(self, after);
1154:         if (!after_readable)
1155:         {
1156:             ReportUnsafe(ErrorCode::HookTransaction);
1157:             return;
1158:         }
1159:         NativeEvent event = Event(EventKind::AlternateOwnerExit, Phase::GameplayUpdate);
1160:         event.return_rva = ReturnRva(_ReturnAddress());
1161:         event.value_bits = after;
1162:         event.original_calls = 1;
1163:         event.flags |= kFlagOriginalCalled;
1164:         Publish(event);
1165:     }
1166: }
