10: struct RelativeCallPatch {
11:     std::uint8_t* call = nullptr;
12:     std::uint8_t expected[5]{};
13:     void* replacement = nullptr;
14:     void* original = nullptr;
15:     std::int32_t original_displacement = 0;
16:     std::int32_t replacement_displacement = 0;
17:     bool installed = false;
18: };
19: 
20: struct PointerPatch {
21:     void** slot = nullptr;
22:     void* replacement = nullptr;
23:     void* original = nullptr;
24:     const wchar_t* expected_owner = nullptr;
25:     bool installed = false;
26:     // Optional frozen-target value.  Prepare validates it before suspension and Apply
27:     // validates the captured value again while every peer thread is suspended.
28:     void* expected_original = nullptr;
29: };
30: 
31: // A type-erased view used when a catalog assigns one global ordinal space to
32: // relative-call and pointer patches. Exactly one patch pointer must be non-null.
33: // The descriptor does not own the patch; the caller must keep both alive for the
34: // complete install/restore lifetime.
35: struct OrderedPatchDescriptor {
36:     std::uint32_t ordinal = UINT32_MAX;
37:     RelativeCallPatch* relative = nullptr;
38:     PointerPatch* pointer = nullptr;
39: };

174: bool Prepare(RelativeCallPatch& patch) noexcept
175: {
176:     if (!patch.call || !patch.replacement || std::memcmp(patch.call, patch.expected, 5) != 0 ||
177:         patch.installed)
178:         return false;
179:     patch.original_displacement = *reinterpret_cast<const std::int32_t*>(patch.call + 1);
180:     patch.original = patch.call + 5 + patch.original_displacement;
181:     const auto next = static_cast<std::int64_t>(reinterpret_cast<std::uintptr_t>(patch.call + 5));
182:     const auto replacement =
183:         static_cast<std::int64_t>(reinterpret_cast<std::uintptr_t>(patch.replacement));
184:     const auto displacement = replacement - next;
185:     if (displacement < (std::numeric_limits<std::int32_t>::min)() ||
186:         displacement > (std::numeric_limits<std::int32_t>::max)())
187:         return false;
188:     patch.replacement_displacement = static_cast<std::int32_t>(displacement);
189:     return true;
190: }
191: 
192: bool Prepare(PointerPatch& patch) noexcept
193: {
194:     if (!patch.slot || !patch.replacement || patch.installed)
195:         return false;
196:     patch.original = *patch.slot;
197:     return patch.original && patch.original != patch.replacement &&
198:            (!patch.expected_original || patch.original == patch.expected_original) &&
199:            (!patch.expected_owner || IsAddressOwnedBy(patch.original, patch.expected_owner));
200: }
201: 
202: bool Apply(RelativeCallPatch& patch, DWORD* failure_error = nullptr) noexcept
203: {
204:     if (std::memcmp(patch.call, patch.expected, sizeof(patch.expected)) != 0)
205:     {
206:         if (failure_error)
207:             *failure_error = ERROR_INVALID_DATA;
208:         return false;
209:     }
210:     const bool complete = ProtectWrite(patch.call + 1, &patch.replacement_displacement,
211:                                        sizeof(patch.replacement_displacement),
212:                                        PAGE_EXECUTE_READWRITE, failure_error);
213:     patch.installed =
214:         *reinterpret_cast<const std::int32_t*>(patch.call + 1) == patch.replacement_displacement;
215:     return complete && patch.installed;
216: }
217: 
218: bool Apply(PointerPatch& patch, DWORD* failure_error = nullptr) noexcept
219: {
220:     if (*patch.slot != patch.original ||
221:         (patch.expected_original && patch.original != patch.expected_original))
222:     {
223:         if (failure_error)
224:             *failure_error = ERROR_INVALID_DATA;
225:         return false;
226:     }
227:     const bool complete =
228:         ProtectWrite(patch.slot, &patch.replacement, sizeof(patch.replacement), PAGE_READWRITE,
229:                      failure_error);
230:     patch.installed = *patch.slot == patch.replacement;
231:     return complete && patch.installed;
232: }
233: 
234: bool Restore(RelativeCallPatch& patch, DWORD* failure_error = nullptr) noexcept
235: {
236:     if (!patch.installed)
237:         return true;
238:     if (*reinterpret_cast<const std::int32_t*>(patch.call + 1) !=
239:         patch.replacement_displacement)
240:     {
241:         if (failure_error)
242:             *failure_error = ERROR_INVALID_DATA;
243:         return false;
244:     }
245:     if (!ProtectWrite(patch.call + 1, &patch.original_displacement,
246:                       sizeof(patch.original_displacement), PAGE_EXECUTE_READWRITE,
247:                       failure_error))
248:         return false;
249:     patch.installed = false;
250:     return true;
251: }
252: 
253: bool Restore(PointerPatch& patch, DWORD* failure_error = nullptr) noexcept
254: {
255:     if (!patch.installed)
256:         return true;
257:     if (*patch.slot != patch.replacement)
258:     {
259:         if (failure_error)
260:             *failure_error = ERROR_INVALID_DATA;
261:         return false;
262:     }
263:     if (!ProtectWrite(patch.slot, &patch.original, sizeof(patch.original), PAGE_READWRITE,
264:                       failure_error))
265:         return false;
266:     patch.installed = false;
267:     return true;

520: bool InstallOrderedPatchTransaction(OrderedPatchDescriptor* patches,
521:                                     std::size_t patch_count,
522:                                     PatchTransactionFailure* failure) noexcept
523: {
524:     if (failure)
525:         *failure = {};
526:     if ((!patches && patch_count) || patch_count > UINT32_MAX)
527:     {
528:         if (failure)
529:             *failure = {PatchFailureStage::InvalidArguments, UINT32_MAX,
530:                         ERROR_INVALID_PARAMETER};
531:         return false;
532:     }
533:     const std::uint32_t first_ordinal = patch_count ? patches[0].ordinal : 0;
534:     for (std::size_t index = 0; index < patch_count; ++index)
535:     {
536:         auto& descriptor = patches[index];
537:         if (descriptor.ordinal != first_ordinal + index ||
538:             (descriptor.relative == nullptr) == (descriptor.pointer == nullptr))
539:         {
540:             if (failure)
541:                 *failure = {PatchFailureStage::InvalidArguments,
542:                             static_cast<std::uint32_t>(index),
543:                             ERROR_INVALID_PARAMETER};
544:             return false;
545:         }
546: #if defined(ISAAC_CS_T0_TESTING)
547:         const PatchTestFaultStage prepare_stage = descriptor.relative
548:                                                      ? PatchTestFaultStage::PrepareRelative
549:                                                      : PatchTestFaultStage::PreparePointer;
550:         if (TestFault(prepare_stage, static_cast<std::uint32_t>(index)))
551:         {
552:             if (failure)
553:                 *failure = {descriptor.relative ? PatchFailureStage::PrepareRelative
554:                                                 : PatchFailureStage::PreparePointer,
555:                             static_cast<std::uint32_t>(index), ERROR_ACCESS_DENIED};
556:             return false;
557:         }
558: #endif
559:         const bool prepared = descriptor.relative ? Prepare(*descriptor.relative)
560:                                                   : Prepare(*descriptor.pointer);
561:         if (!prepared)
562:         {
563:             if (failure)
564:                 *failure = {descriptor.relative ? PatchFailureStage::PrepareRelative
565:                                                 : PatchFailureStage::PreparePointer,
566:                             static_cast<std::uint32_t>(index), ERROR_INVALID_DATA};
567:             return false;
568:         }
569:     }

578:     SuspendedThreads threads;
579:     if (!threads.SuspendAll(failure))
580:         return false;
581: #if defined(ISAAC_CS_T0_TESTING)
582:     if (TestFault(PatchTestFaultStage::ThreadSuspend, 0))
583:     {
584:         if (failure)
585:             *failure = {PatchFailureStage::ThreadSuspend, 0, ERROR_ACCESS_DENIED};
586:         return false;
587:     }
588: #endif
589:     std::size_t applied = 0;
590:     bool apply_failed = false;
591:     for (; applied < patch_count; ++applied)
592:     {
593:         auto& descriptor = patches[applied];
594:         DWORD apply_error = ERROR_SUCCESS;
595: #if defined(ISAAC_CS_T0_TESTING)
596:         const PatchTestFaultStage apply_stage = descriptor.relative
597:                                                    ? PatchTestFaultStage::ApplyRelative
598:                                                    : PatchTestFaultStage::ApplyPointer;
599:         const bool injected =
600:             TestFault(apply_stage, static_cast<std::uint32_t>(applied)) ||
601:             TestFault(PatchTestFaultStage::Protect,
602:                       static_cast<std::uint32_t>(applied));
603: #else
604:         const bool injected = false;
605: #endif
606:         bool complete = !injected &&
607:                               (descriptor.relative
608:                                    ? Apply(*descriptor.relative, &apply_error)
609:                                    : Apply(*descriptor.pointer, &apply_error));

628:             ++applied;
629:         if (failure)
630:             *failure = {descriptor.relative ? PatchFailureStage::ApplyRelative
631:                                             : PatchFailureStage::ApplyPointer,
632:                         static_cast<std::uint32_t>(descriptor.ordinal), apply_error};
633:         break;
634:     }
635:     if (!apply_failed && applied == patch_count)
636:         return true;
637: 
638:     bool rollback_failure = false;
639:     while (applied)
640:     {
641:         auto& descriptor = patches[--applied];
642:         DWORD restore_error = ERROR_SUCCESS;
643: #if defined(ISAAC_CS_T0_TESTING)
644:         const PatchTestFaultStage rollback_stage = descriptor.relative
645:                                                       ? PatchTestFaultStage::RollbackRelative
646:                                                       : PatchTestFaultStage::RollbackPointer;
647:         const bool injected =
648:             TestFault(rollback_stage, static_cast<std::uint32_t>(descriptor.ordinal));
649: #else
650:         const bool injected = false;
651: #endif
652:         const bool restored = !injected &&
653:                               (descriptor.relative
654:                                    ? Restore(*descriptor.relative, &restore_error)
655:                                    : Restore(*descriptor.pointer, &restore_error));
656: #if defined(ISAAC_CS_T0_TESTING)
657:         if (g_ordered_test_observer)
658:             g_ordered_test_observer(OrderedPatchTestOperation::Rollback, descriptor.ordinal, restored);
659: #endif
660:         if (!restored && !rollback_failure)
661:         {
662:             rollback_failure = true;
663:             if (failure)
664:                 *failure = {descriptor.relative ? PatchFailureStage::RollbackRelative
665:                                                 : PatchFailureStage::RollbackPointer,
666:                             static_cast<std::uint32_t>(descriptor.ordinal), restore_error};
667:         }
668:     }
669:     return false;
670: }
