672: bool RestoreOrderedPatchTransaction(OrderedPatchDescriptor* patches,
673:                                     std::size_t patch_count) noexcept
674: {
675:     if ((!patches && patch_count) || patch_count > UINT32_MAX)
676:         return false;
677:     const std::uint32_t first_ordinal = patch_count ? patches[0].ordinal : 0;
678:     for (std::size_t index = 0; index < patch_count; ++index)
679:     {
680:         const auto& descriptor = patches[index];
681:         if (descriptor.ordinal != first_ordinal + index ||
682:             (descriptor.relative == nullptr) == (descriptor.pointer == nullptr))
683:             return false;
684:     }
685:     SuspendedThreads threads;
686:     if (!threads.SuspendAll(nullptr))
687:         return false;
688:     bool restored = true;
689:     for (std::size_t index = patch_count; index > 0; --index)
690:     {
691:         auto& descriptor = patches[index - 1];
692: #if defined(ISAAC_CS_T0_TESTING)
693:         const PatchTestFaultStage restore_stage = descriptor.relative
694:                                                      ? PatchTestFaultStage::RestoreRelative
695:                                                      : PatchTestFaultStage::RestorePointer;
696:         if (TestFault(restore_stage,
697:                       static_cast<std::uint32_t>(descriptor.ordinal)))
698:         {
699:             restored = false;
700:             if (g_ordered_test_observer)
701:                 g_ordered_test_observer(OrderedPatchTestOperation::Restore, descriptor.ordinal, false);
702:             continue;
703:         }
704: #endif
705:         const bool current_restored = descriptor.relative ? Restore(*descriptor.relative)
706:                                                           : Restore(*descriptor.pointer);
707: #if defined(ISAAC_CS_T0_TESTING)
708:         if (g_ordered_test_observer)
709:             g_ordered_test_observer(OrderedPatchTestOperation::Restore, descriptor.ordinal, current_restored);
710: #endif
711:         restored = current_restored && restored;
712:     }
713:     return restored;

