101:     EntityList* entityList = g_Game->_room->GetEntityList();
102: 
103:     auto remove_entities = [](EntityList_EL* list, bool entityOwner)
104:     {
105:         for (int i = (int)list->_size - 1; i >= 0; i--)
106:         {
107:             Entity* entity = list->_data[i];
108:             if (entity->_exists)
109:             {
110:                 continue;
111:             }
112: 
113:             if (entityOwner)
114:             {
115:                 bool isPlayer = entity->_type == eEntityType::ENTITY_PLAYER;
116:                 if (!isPlayer)
