121:                 bool wasValid = entity->_valid;
122:                 entity->ClearReferences();
123:                 entity->_valid = false;
124: 
125:                 if (isPlayer && wasValid)
126:                 {
127:                     unsigned int deallocate = 0x1;
128:                     entity->Free(deallocate);
