22: void InitEntityPlusHolder(Entity* entity) {
23: 	// Create an EntityPlusHolder.
24: 	EntityPlusHolder* holder = new EntityPlusHolder();
25: 
26: 	// Cut the pointer to it in half.
27: 	uintptr_t val = (uintptr_t)holder;
28: 	unsigned short up = (val & 0xFFFF0000) >> 16;
29: 	unsigned short low = val & 0x0000FFFF;
30: 
31: 	// Store the half-pointers in unused boolean padding.
32: 	entity->_entityExtraDataPtrUpperBytes = up;
33: 	entity->_entityExtraDataPtrLowerBytes = low;
34: }
35: 
36: EntityPlusHolder* GetEntityPlusHolder(Entity* entity, const bool initIfMissing) {
37: 	if (entity->_entityExtraDataPtrUpperBytes == 0 && entity->_entityExtraDataPtrLowerBytes == 0) {
38: 		if (initIfMissing) {
39: 			g_Game->GetConsole()->PrintError("[REPENTOGON] EntityPlusHolder was not initialized!\n");
40: 			// Since the EntityPlusHolder is initialized in the Entity constructor,
41: 			// this should never happen, but leaving this here for now just in case.
42: 			InitEntityPlusHolder(entity);
43: 		}
44: 		else {
45: 			return nullptr;
46: 		}
47: 	}
48: 
49: 	// Get the two pointer halves.
50: 	const unsigned short up = entity->_entityExtraDataPtrUpperBytes;
51: 	const unsigned short low = entity->_entityExtraDataPtrLowerBytes;
52: 
53: 	// Re-combine them.
54: 	const uintptr_t val = ((uintptr_t)up << 16) + low;
55: 
56: 	// Return the reconstructed pointer.
57: 	return (EntityPlusHolder*)val;
58: }
